"use strict";class ServiceWorkerManager{constructor(offlinePage,debugMode){this.CACHE_VERSION='v1';this.CACHE_KEYS=[this.CACHE_VERSION];this.offlinePage=offlinePage;this.debugMode=debugMode;this.init();}init(){self.addEventListener("install",this.onInstall.bind(this));self.addEventListener("activate",this.onActivate.bind(this));self.addEventListener("fetch",this.onFetch.bind(this));self.addEventListener('message',this.onMessage.bind(this));}debug(message){if(this.debugMode){console.log(message);}}onInstall(event){this.debug("Installing Service Worker");event.waitUntil(this.cacheOfflinePage().then(()=>self.skipWaiting()).catch((error)=>{this.debug(`Install event error:${error}`);}));}onActivate(event){this.debug("Activating Service Worker");event.waitUntil(this.clearOldCaches().then(()=>self.clients.claim()).catch((error)=>{this.debug(`Activate event error:${error}`);}));}onFetch(event){}onMessage(event){if(event.data.action==='skipWaiting'){self.skipWaiting();}}handleFetchError(request,error){}cacheOfflinePage(){this.debug("Cache offline page");return caches.open(this.CACHE_VERSION).then(cache=>cache.addAll([this.offlinePage]));}clearOldCaches(){this.debug("Clean old caches");return caches.keys().then(keys=>Promise.all(keys.filter(key=>!this.CACHE_KEYS.includes(key)).map(key=>caches.delete(key))));}}new ServiceWorkerManager("/offline/index.html",false);